import Container from "@/components/Container";
import AssetCard from "@/components/AssetCard";
import { assets } from "@/data/mockData";
import { Search, Filter, SlidersHorizontal, ChevronRight } from "lucide-react";
import Link from "next/link";

export const metadata = {
    title: "Assets Library",
    description: "Browse our collection of free and premium design assets, overlays, LUTs, and more.",
};

const mainCategories = ["All", "Thumbnails", "Templates", "Overlays", "UI Kits", "LUTs", "Fonts"];
const filterGroups = [
    { name: "License", options: ["Free", "Premium", "Editorial"] },
    { name: "Format", options: ["PSD", "AI", "MP4", "CUBE", "FIG"] },
    { name: "Orientation", options: ["Horizontal", "Vertical", "Square"] },
];

export default async function AssetsPage({
    searchParams
}: {
    searchParams: Promise<{ cat?: string, q?: string }>
}) {
    const { cat: activeCat, q: query } = await searchParams;

    const filteredAssets = activeCat
        ? assets.filter(a => a.category.toLowerCase().includes(activeCat.toLowerCase()))
        : assets;

    return (
        <div className="bg-background min-h-screen">
            {/* Top Breadcrumb/Meta info (Freepik style) */}
            <div className="border-b border-border py-6 bg-zinc-50 dark:bg-zinc-950/20">
                <Container>
                    <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                        <div>
                            <div className="flex items-center text-[10px] font-bold uppercase tracking-widest text-secondary mb-2">
                                <Link href="/" className="hover:text-foreground">HOME</Link>
                                <ChevronRight size={10} className="mx-2" />
                                <span>ASSETS</span>
                            </div>
                            <h1 className="text-3xl font-black uppercase tracking-tighter">
                                {activeCat ? `${activeCat} Resources` : "All Creative Assets"}
                            </h1>
                        </div>
                        <div className="flex items-center gap-4">
                            <span className="text-xs font-bold text-secondary uppercase tracking-widest">{filteredAssets.length} Results</span>
                        </div>
                    </div>
                </Container>
            </div>

            <Container className="py-10">
                <div className="flex flex-col lg:flex-row gap-8">

                    {/* Sidebar Filters (Freepik Style) */}
                    <aside className="hidden lg:block w-64 shrink-0">
                        <div className="sticky top-28 space-y-10">
                            <div className="flex items-center justify-between border-b border-border pb-4">
                                <h3 className="text-sm font-black uppercase tracking-widest flex items-center gap-2">
                                    <Filter size={16} /> Filters
                                </h3>
                                <button className="text-[10px] font-bold underline text-secondary uppercase tracking-widest">Reset</button>
                            </div>

                            {filterGroups.map((group) => (
                                <div key={group.name}>
                                    <h4 className="text-xs font-black uppercase tracking-widest mb-4">{group.name}</h4>
                                    <div className="space-y-3">
                                        {group.options.map((opt) => (
                                            <label key={opt} className="flex items-center group cursor-pointer">
                                                <div className="w-4 h-4 border border-border flex items-center justify-center group-hover:border-foreground transition-colors mr-3">
                                                    <div className="w-2 h-2 bg-foreground scale-0 group-has-[:checked]:scale-100 transition-transform" />
                                                </div>
                                                <input type="checkbox" className="hidden" />
                                                <span className="text-xs font-medium text-secondary group-hover:text-foreground transition-colors">{opt}</span>
                                            </label>
                                        ))}
                                    </div>
                                </div>
                            ))}

                            <div className="pt-8 mt-8 border-t border-border">
                                <p className="text-[11px] text-secondary font-medium leading-relaxed italic">
                                    Search tip: Use specific keywords like &quot;monochromatic&quot; or &quot;grainy&quot; for better results.
                                </p>
                            </div>
                        </div>
                    </aside>

                    {/* Main Content Area */}
                    <div className="flex-grow">
                        {/* Horizontal Sub-category Pills */}
                        <div className="flex items-center gap-3 mb-10 overflow-x-auto no-scrollbar pb-2">
                            <div className="bg-foreground text-background p-2.5 shrink-0 hover:opacity-90 cursor-pointer">
                                <SlidersHorizontal size={16} />
                            </div>
                            {mainCategories.map(cat => (
                                <Link
                                    key={cat}
                                    href={`/assets?cat=${cat.toLowerCase().replace(' ', '-')}`}
                                    className={`px-5 py-2.5 text-[11px] font-black uppercase tracking-widest border transition-all shrink-0 ${(activeCat === cat.toLowerCase()) || (!activeCat && cat === "All")
                                        ? "bg-foreground text-background border-foreground"
                                        : "bg-background text-foreground border-border hover:border-foreground"
                                        }`}
                                >
                                    {cat}
                                </Link>
                            ))}
                        </div>

                        {/* Assets Grid - Uniform & High Quality */}
                        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                            {filteredAssets.map((asset, idx) => (
                                <AssetCard key={`${asset.id}-${idx}`} asset={asset} />
                            ))}
                        </div>

                        {/* Pagination Placeholder */}
                        <div className="mt-20 flex justify-center">
                            <button className="px-12 py-4 border-2 border-foreground font-black uppercase tracking-widest hover:bg-foreground hover:text-background transition-all">
                                Load More Resources
                            </button>
                        </div>
                    </div>
                </div>
            </Container>
        </div>
    );
}
